class Solution {
    public int[][] matrixReshape(int[][] mat, int r, int c) {
        int rows = mat.length;
        int cols = mat[0].length;
        if (rows * cols != r * c) {
            return mat;
        }

        int[][] reshaped = new int[r][c];
        for (int index = 0; index < rows * cols; index++) {
            reshaped[index / c][index % c] = mat[index / cols][index % cols];
        }
        return reshaped;
    }
}

class Solution {
    public int[][] matrixReshape(int[][] mat, int r, int c) {
        int rows = mat.length;
        int cols = mat[0].length;
        if (rows * cols != r * c) {
            return mat;
        }

        int[][] reshaped = new int[r][c];
        int targetRow = 0;
        int targetCol = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                reshaped[targetRow][targetCol] = mat[i][j];
                targetCol++;
                if (targetCol == c) {
                    targetCol = 0;
                    targetRow++;
                }
            }
        }
        return reshaped;
    }
}

class Solution {
    public int[][] matrixReshape(int[][] mat, int r, int c) {
        int rows = mat.length;
        int cols = mat[0].length;
        if (rows * cols != r * c) {
            return mat;
        }

        int[] flat = new int[rows * cols];
        int write = 0;
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                flat[write++] = mat[i][j];
            }
        }

        int[][] reshaped = new int[r][c];
        int read = 0;
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                reshaped[i][j] = flat[read++];
            }
        }
        return reshaped;
    }
}

class Solution {
    public int[][] matrixReshape(int[][] mat, int r, int c) {
        int rows = mat.length;
        int cols = mat[0].length;
        if (rows * cols != r * c) {
            return mat;
        }

        java.util.ArrayDeque<Integer> values = new java.util.ArrayDeque<>();
        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < cols; j++) {
                values.addLast(mat[i][j]);
            }
        }

        int[][] reshaped = new int[r][c];
        for (int i = 0; i < r; i++) {
            for (int j = 0; j < c; j++) {
                reshaped[i][j] = values.removeFirst();
            }
        }
        return reshaped;
    }
}
